function officeMiniaturen(layer) {
  layer.querySelectorAll(".fvgl-bild[data-fvgl-url]").forEach((el) => {
    const f = { url: el.dataset.fvglUrl, n: el.dataset.fvglN || "" };
    if (!f.url || !OFFICE.test(f.n)) return;
    el.classList.add("ms-fvgl-office");
    el.title = "Antippen zum Vergrößern";
    const zeichnen = () => {
      el.innerHTML = '<button type="button" class="btn small ms-fvgl-klein">Kleiner</button>';
      const box = document.createElement("div");
      el.appendChild(box);
      officeVorschau(box, f);
    };
    zeichnen();
    el.addEventListener("click", (e) => {
      const fig = el.closest(".fvgl");
      if (!fig) return;
      if (!fig.classList.contains("gross")) { fig.classList.add("gross"); zeichnen(); }
      else if (e.target.closest(".ms-fvgl-klein")) { fig.classList.remove("gross"); zeichnen(); }
    });
  });
}

